internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"TOKENS","outputs":[{"internalType":"contract GameToken","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"owner","type":"address"},{"internalType":"address payable","name":"stipendTo","type":"address"},{"internalType":"uint256","name":"stipend","type":"uint256"}],"name":"purchase","outputs":[],"stateMutability":"payable","type":"function"},{"inputs":[{"internalType":"contract IGameStake","name":"game","type":"address"},{"internalType":"address","name":"owner","type":"address"},{"internalType":"address payable","name":"stipendTo","type":"address"},{"internalType":"uint256","name":"stipend","type":"uint256"}],"name":"purchaseAt","outputs":[],"stateMutability":"payable","type":"function"},{"inputs":[{"internalType":"uint256","name":"amount","type":"uint256"},{"internalType":"address payable","name":"to","type":"address"}],"name":"redeem","outputs":[],"stateMutability":"nonpayable","type":"function"}],"devdoc":{"details":"A new player needs two unrelated things before their first move: a      stake (or this game has no reason for anyone to reveal) and gas in the      local key that signs their moves. Asking for those separately is two      wallet prompts, and the second one arrives after the first has just      spent the wallet down.      So the call does both. `msg.value` is split: `stipend` goes to the key      that will play, and the remainder must equal `PRICE` exactly. The stake      itself is credited to `player` by the game, from tokens this contract      mints and stakes on their behalf, which is what removes the      mint/approve/stake sequence a player used to sign three times.      THE PAYER IS NOT THE PLAYER, deliberately, and that is inherited from      `addToReserve(player, amount)`: whoever sends this pays, and `player` is      credited. An account with no wallet of its own (email or social      sign-in) can therefore be set up by somebody else's wallet, and topping      up a stranger's reserve is a gift rather than an attack, because only      its owner can ever withdraw it.      THE SALE KEEPS THE ETH, and it is the token's only minter      (`GameToken.setMinter`), so every token in circulation was paid for      at `PRICE` per `AMOUNT` and {redeem} buys tokens back at that same      price from that ETH: ETH in, ETH out      (`docs/adr/0006-stake-erc20-reserve-exit-only.md`). Tokens burned by an      unrevealed deployment leave their ETH here as surplus.","errors":{"WrongPaymentAmount(uint256,uint256)":[{"details":"Exact rather than a minimum: a client that sizes the value from the      price alone, and separately asks for a stipend, would otherwise      silently overpay by the stipend on every purchase."}]},"events":{"Staked(address,address,uint256,address,uint256)":{"details":"`sender` is kept apart from `owner` because they are routinely      different addresses, and reading the log as though they were the      same is how a payer gets mistaken for a participant."}},"kind":"dev","methods":{"purchase(address,address,uint256)":{"details":"AN ADDRESS HERE AND A `uint256` AT THE GAME, deliberately. The sale      is where an account turns into whatever this game plays as, which      is why the widening happens in THIS contract and not in the client:      a game whose identity is a token mints one here instead, and the      rail above (`web/src/lib/game/acquire`) sends the same call with      the same arguments either way.The stipend is sized by the CLIENT, not here, because what it is        worth is a number of turns at the chain's gas price and only the        client knows both. This contract's job is only to make it one        transaction.","params":{"owner":"The account the stake is credited to. Not necessarily the        caller: see the note on the contract.","stipend":"How much of `msg.value` is gas for that key rather than        payment for the stake.","stipendTo":"The local key to forward gas to, or the zero address        when there is none, in which case `stipend` must be zero and        `msg.value` is the price alone."}},"purchaseAt(address,address,address,uint256)":{"details":"Open to any address on purpose. The tokens are minted for this      purchase alone and approved to `game` alone, so a `game` that is not      one only ever takes what its own buyer paid for."},"redeem(uint256,address)":{"details":"The tokens are BURNED, so the supply and the ETH backing it fall      together and the sale stays solvent whoever redeems first. Rounded      down, which can only leave the sale more solvent. What the game's      `exit` calls with an exiting army's stake."}},"version":1},"userdoc":{"errors":{"WrongPaymentAmount(uint256,uint256)":[{"notice":"`msg.value` minus the stipend was not the price."}]},"events":{"Redeemed(address,address,uint256,uint256)":{"notice":"`amount` tokens of `sender` bought back, paid to `to`."},"Staked(address,address,uint256,address,uint256)":{"notice":"One player set up: staked, and their play key funded."}},"kind":"user","methods":{"AMOUNT()":{"notice":"How much stake one purchase credits."},"PRICE()":{"notice":"What one stake costs, in the chain's own currency. May be zero."},"purchase(address,address,uint256)":{"notice":"Stake for `owner`, and fund the key that will play for them."},"purchaseAt(address,address,address,uint256)":{"notice":"{purchase}, for another game played with the same token: a         table for a fixed set of players, cloned per game by a factory,         which no immutable here could name in advance."},"redeem(uint256,address)":{"notice":"Sell `amount` of the caller's tokens back at the fixed price,         paid in ETH to `to`, from the ETH the purchases left here."}},"notice":"Acquiring what lets you play, in ONE transaction.","version":1}},"settings":{"compilationTarget":{"project/src/tokens/StakeSale.sol":"StakeSale"},"evmVersion":"london","libraries":{},"metadata":{"bytecodeHash":"ipfs","useLiteralContent":true},"optimizer":{"enabled":true,"runs":999999},"remappings":["project/:@etherplay/delegation/=npm/@etherplay/delegation@0.1.2/","project/:solidity-kit/=npm/solidity-kit@0.5.7/"]},"sources":{"npm/@etherplay/delegation@0.1.2/contracts/IDelegation.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @title IDelegation
/// @notice The delegation entry points as a type, for code that has to NAME
/// them rather than inherit them.
///
/// {UsingDelegation} already writes these functions, so a contract that
/// inherits it needs nothing from here. This exists for the cases where the
/// implementation is not the thing being described:
///
///  - A contract behind a ROUTER cannot say "these selectors are mine" by
///    inheriting an abstract contract: the router needs a list of selectors,
///    composed from interfaces, while the implementation lives elsewhere.
///    Without a shared declaration every router restates the same six
///    signatures, and a restatement is a copy that can drift.
///  - A client, a script or a test that calls into a contract it does not
///    compile against - `IDelegation(target).delegationStatus(owner, delegate)`
///    - which is also the shape the TypeScript side of this package exports as
///    `DELEGATION_ABI`, checked against this file by a test.
///
/// DO NOT WRITE `is IDelegation, UsingDelegation`. It does not compile without
/// restating all six functions as `override`, which is exactly the boilerplate
/// {UsingDelegation} exists to spare an adopter. Inherit the implementation
/// alone and use this interface where a TYPE is wanted; the two agreeing is
/// covered by a test (test/solidity/IDelegation.t.sol), and on a router the
/// thing that actually breaks is a selector that does not route - a missing
/// route in the deploy script, or two routes claiming the same selector - which
/// no compiler check would have caught.
///
/// The whole external surface, in the order {UsingDelegation} declares it, so
/// the two can be read side by side.
///
/// There is no `delegateOf`. An account may have several delegates, so no
/// single address could be returned without being a lie, and the set is
/// reconstructed from `DelegationChanged` logs rather than read. Every caller
/// only ever asked about a pair anyway.
interface IDelegation {
    /// @notice authorise `delegate` to act for you here, and optionally fund it.
    function registerDelegate(
        address delegate,
        address payable payee
    ) external payable;

    /// @notice authorise `delegate` to act for `owner` here, proven by `owner`'s
    /// signature, and fund that delegate with whatever value is sent.
    function registerDelegateViaSignature(
        address owner,
        address delegate,
        uint256 deadline,
        bytes calldata signature
    ) external payable;

    /// @notice withdraw your authorisation of `delegate`; no signature can put
    /// that one back.
    function revokeDelegate(address delegate) external;

    /// @notice whether `delegate` may act for `owner` here, and whether `owner`
    /// withdrew it.
    function delegationStatus(
        address owner,
        address delegate
    ) external view returns (bool allowed, bool withdrawn);

    /// @notice the exact text an owner signs to authorise `delegate` here.
    function delegationMessage(
        address delegate,
        uint256 deadline
    ) external view returns (string memory);

    /// @notice the EIP-191 digest of {delegationMessage}.
    function delegationDigest(
        address delegate,
        uint256 deadline
    ) external view returns (bytes32);
}
