pragma solidity ^0.8.0;

import "./UsingERC20Events.sol";

interface IERC20 is UsingERC20Events {
    /// @notice Returns the total token supply.
    function totalSupply() external view returns (uint256);

    /// @notice Returns the number of decimals the token uses.
    function decimals() external view returns (uint8);

    /// @notice Returns the symbol of the token.
    function symbol() external view returns (string memory);

    /// @notice Returns the name of the token.
    function name() external view returns (string memory);

    /// @notice Returns the account balance of another account with address `owner`.
    function balanceOf(address owner) external view returns (uint256);

    /// @notice Transfers `amount` of tokens to address `to`.
    function transfer(address to, uint256 amount) external returns (bool);

    /// @notice Returns the amount which `spender` is still allowed to withdraw from `owner`.
    function allowance(address owner, address spender) external view returns (uint256);

    /// @notice Allows `spender` to withdraw from your account multiple times, up to `amount`.
    function approve(address spender, uint256 amount) external returns (bool);

    /// @notice Transfers `amount` tokens from address `from` to address `to`.
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}
","keccak256":"0x3a6bcd5cf1d9e50fbe405f4c6c9c868e97ce2a84ae99fd7c1fb2d916c4d5debd","license":"MIT"},"npm/solidity-kit@0.5.7/solc_0_8/ERC20/interfaces/IERC20WithCallback.sol":{"content":"// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "../interfaces/IERC20.sol";

interface ITransferReceiver {
    /// @notice called by ERC20 token after transfer been executed.
    /// @param payer account sending the money
    /// @param amount number of token transfered
    /// @param data extra data
    function onTokenTransfer(
        address payer,
        uint256 amount,
        bytes calldata data
    ) external returns (bool);
}

interface ITransferOnBehalfReceiver {
    /// @notice called by ERC20 token after transfer been executed.
    /// @param payer account sending the money
    /// @param forAddress account to be considered as te actual payer
    /// @param amount number of token transfered
    /// @param data extra data
    function onTokenTransferedOnBehalf(
        address payer,
        address forAddress,
        uint256 amount,
        bytes calldata data
    ) external returns (bool);
}

interface IApprovalReceiver {
    /// @notice called by ERC20 token after transfer been executed.
    /// @param owner account that grant the approval
    /// @param amount number of token approved
    /// @param data extra data
    function onTokenApproval(
        address owner,
        uint256 amount,
        bytes calldata data
    ) external returns (bool);
}

interface IERC20WithCallback is IERC20 {
    /// @notice transfer `amount` token to `to` and callback into it via `onTokenTransfer`
    /// @param to account to receive the tokens
    /// @param amount number of token to transfer
    /// @param data extra data
    /// @return success
    function transferAndCall(
        address to,
        uint256 amount,
        bytes calldata data
    ) external returns (bool);

    /// @notice transfer `amount` token to `to` and callback into it via `onTokenTransfer`
    /// @param from account to send the token from
    /// @param to account to receive the tokens
    /// @param amount number of token to transfer
    /// @param data extra data
    /// @return success
    function transferFromAndCall(
        address from,
        address to,
        uint256 amount,
        bytes calldata data
    ) external returns (bool);

    /// @notice transfer `amount` token to `to` and callback into it via `onTokenTransferedOnBehalf`
    /// @param forAddress account to send the token for
    /// @param to account to receive the tokens
    /// @param amount number of token to transfer
    /// @param data extra data
    /// @return success
    function transferOnBehalfAndCall(
        address forAddress,
        address to,
        uint256 amount,
        bytes calldata data
    ) external returns (bool);

    /// @notice approve `amount` token to be spent by `spender` and callback into it via `onTokenApproval`
    /// @param spender account to send the token for
    /// @param amount number of token to transfer
    /// @param data extra data
    /// @return success
    function approveAndCall(
        address spender,
        uint256 amount,
        bytes calldata data
    ) external returns (bool);
}
